// フォームの入力から members/<id>.yaml の内容を組み立て、PR の材料にする。
// フォームは PR を作るための補助 UI にすぎず、以降の経路は直接 PR と同一。
// 検証の正は台帳リポジトリの CI(直接 PR にも効かせるため)。
// 設計: docs/design/01-member-lifecycle.md#申請の入口2つ

const YAML = require('yaml');
const f = $input.first()?.json ?? {};
const get = (k) => (f[k] ?? '').toString().trim();

const kindLabel = get('申請の種類');
const op = kindLabel.startsWith('追加') ? 'add'
  : kindLabel.startsWith('役割変更') ? 'change'
  : kindLabel.startsWith('削除') ? 'remove' : null;
if (!op) throw new Error(`申請の種類が不正です: ${kindLabel}`);

const email = get('メールアドレス');
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) throw new Error(`メールアドレスの形式が不正です: ${email}`);

// id はメールアドレスのローカル部を正規化したもの(台帳の規則)
const id = email.split('@')[0].toLowerCase().replace(/\+.*$/, '').replace(/[^a-z0-9._-]/g, '-');

const teams = get('所属チーム').split(',').map((s) => s.trim()).filter(Boolean);
const affiliation = get('所属区分') === '協力会社'
  ? `partner:${get('協力会社名') || '(会社名未記入)'}`
  : 'employee';

let doc;
if (op === 'remove') {
  // 既存ファイルを読んで status だけ変えるのが本来だが、フォームからは
  // 最小限の宣言を作り、CI と差分プレビューでレビューしてもらう。
  doc = { __partial: true, status: 'left', left_at: get('適用日・最終日') || new Date().toISOString().slice(0, 10) };
} else {
  doc = {
    name: get('氏名') || id,
    email,
    affiliation,
    role: get('役割'),
    teams,
    status: 'active',
  };
  const github = get('GitHub ユーザー名');
  if (github) doc.accounts = { github };
  if (affiliation.startsWith('partner:')) {
    doc.sponsor = get('受入責任者のメールアドレス');
    doc.contract_until = get('契約終了日');
  }
  if (op === 'change' && get('適用日・最終日')) doc.effective_from = get('適用日・最終日');
}

const OPNAME = { add: '追加', change: '役割変更・チーム異動', remove: '削除' };
const stamp = new Date().toISOString().replace(/[^0-9]/g, '').slice(0, 14);

return [{ json: {
  op,
  id,
  path: `members/${id}.yaml`,
  partial: doc.__partial === true,
  doc,
  branch: `member/${op}-${id}-${stamp}`,
  title: `${OPNAME[op]}: ${doc.name ?? id}`,
  reason: get('理由・備考'),
  applicantEmail: email,
}}];

// 追加は新規作成、変更・削除は既存に上書き。
// 既存が無いのに変更・削除しようとしたら、その時点で止める。
const YAML = require('yaml');
const ctx = $('申請内容を組み立てる').first().json;
const rec = $input.first()?.json;
const current = rec?.desired ?? null;

if (ctx.op === 'add' && current) {
  throw new Error(`${ctx.id} は既に台帳に存在します。役割変更として申請してください`);
}
if (ctx.op !== 'add' && !current) {
  throw new Error(`${ctx.id} が台帳に見つかりません。メールアドレスを確認してください`);
}

const next = ctx.partial ? { ...current, ...ctx.doc } : ctx.doc;
delete next.__partial;

const lines = [
  `**${ctx.title}**`, '',
  `申請者: ${ctx.applicantEmail}`,
  ctx.reason ? `理由: ${ctx.reason}` : '',
  '',
  'このPRはメンバー申請フォームから自動生成されました。',
  'CI が権限への影響をコメントします。内容を確認してマージしてください。',
].filter(Boolean);

return [{ json: {
  path: ctx.path,
  content: YAML.stringify(next),
  title: ctx.title,
  body: lines.join('\n'),
  branch: ctx.branch,
}}];

